/* Crash Course, part 1 — reading code.
   House rule for this file: explain it the way you would to a smart friend who
   has never written a line. Short sentences. Real examples. Nothing hand-waved. */

TD.add("crash-course", [

{t:"Variable", d:"A named box that holds a value your program can read and change later.", l:"core", g:["basics","syntax","crash-course"],
 b:["When you write `age = 30`, you are telling the computer: remember the number 30, and let me call it `age` from now on. The name is for you — the machine only cares that something is stored somewhere. Every time you write `age` afterwards, the computer swaps in whatever is currently in the box.",
    "The word variable is literal: the value can vary. You can put something new in the box at any time and the old value is simply gone. That is the most common early confusion — a variable is not an equation, it is a label stuck onto a value, and the label can be moved."],
 k:["A name pointing at a value, not a permanent equation.",
    "Assigning again replaces the old value; nothing warns you.",
    "Good names are the cheapest documentation you will ever write.",
    "`=` means put this in the box. `==` means are these the same?"],
 x:{lang:"python", code:"age = 30           # put 30 in a box named age\nage = age + 1      # read the box, add 1, put it back\nname = \"Aryan\"     # boxes can hold text too\nprint(name, age)   # Aryan 31"},
 r:["Constant", "Data Type", "Scope", "Assignment Operator"]},

{t:"Constant", d:"A value you promise never to change after you set it — usually written in CAPITALS.", l:"core", g:["basics","syntax","crash-course"],
 b:["A constant is a variable with a rule attached: set it once, then leave it alone. Some languages enforce this and refuse to run if you reassign it. Others simply rely on the convention that anything in SCREAMING_SNAKE_CASE is off limits.",
    "Constants exist for readability more than safety. `TAX_RATE = 0.18` at the top of a file tells the next reader where the number came from, and it means you change it in one place instead of hunting for `0.18` scattered across two hundred lines."],
 k:["Set once, read many times.",
    "Convention is ALL_CAPS_WITH_UNDERSCORES.",
    "Kills magic numbers by giving them a name.",
    "In JavaScript `const` freezes the label, not the contents of an object."],
 x:{lang:"javascript", code:"const TAX_RATE = 0.18;\nconst API_URL = \"https://api.example.com\";\n\n// const stops reassignment...\n// TAX_RATE = 0.2;   // TypeError\n\n// ...but not mutation of the thing inside\nconst config = { retries: 3 };\nconfig.retries = 5;  // allowed"},
 r:["Variable", "Magic Number", "Naming Conventions"]},

{t:"Data Type", d:"The kind of thing a value is — text, whole number, decimal, true/false, list — which decides what you can do with it.", l:"core", g:["basics","syntax","crash-course"],
 b:["The number 5 and the text \"5\" look identical on screen and are completely different to a computer. One is a number you can multiply; the other is text that happens to contain a digit. Adding two numbers gives 10. Adding two of those strings gives \"55\", because joining text end to end is what plus means for text.",
    "Half the bugs a beginner hits are type bugs: reading a number out of a form gives you text, and suddenly your total is \"1020\" instead of 30. Learning to ask what type is this, actually? is the fastest debugging skill you can pick up."],
 k:["Type decides which operations are legal and what they mean.",
    "Input from forms, files and APIs arrives as text until you convert it.",
    "Convert deliberately: `int(x)`, `Number(x)`, `str(x)`.",
    "Static languages check types before running; dynamic ones find out at runtime."],
 x:{lang:"python", code:"a = 5        # int\nb = \"5\"      # str\nprint(a + a)         # 10\nprint(b + b)         # 55\nprint(a + int(b))    # 10  -- convert first\nprint(type(a), type(b))"},
 r:["String", "Integer", "Boolean", "Type Hint"]},

{t:"String", d:"Text — a sequence of characters wrapped in quotes.", l:"core", g:["basics","syntax","crash-course"],
 b:["Anything in quotes is a string, including an empty one. The quotes are not part of the value; they are punctuation telling the language to treat what sits between them as literal text rather than as code.",
    "Strings are the workhorse type. Names, addresses, JSON, HTML, prompts to a language model — all strings. In most modern languages they are immutable: you never edit a string in place, you build a new one. `name.upper()` hands back a new uppercase string and leaves the original untouched."],
 k:["Quotes mark text; single and double usually mean the same thing.",
    "Immutable in Python, Java and JavaScript — methods return new strings.",
    "`len(s)` counts characters; indexes start at 0.",
    "Joining two strings together is called concatenation."],
 x:{lang:"python", code:"name = \"ada lovelace\"\nprint(name.title())       # Ada Lovelace\nprint(name.upper())       # ADA LOVELACE\nprint(name)               # ada lovelace  -- unchanged\nprint(len(name))          # 12\nprint(name[0], name[-1])  # a e"},
 r:["String Interpolation", "String Concatenation", "Escape Character", "Slicing"]},

{t:"Integer", a:"int", d:"A whole number — no decimal point, positive or negative.", l:"core", g:["basics","syntax","crash-course"],
 b:["Counting things gives you integers: 0, 7, -3, a million. They are stored exactly, so integer arithmetic is trustworthy in a way decimal arithmetic is not. If you are counting users, items in a cart or retries, use an integer.",
    "The catch is division. In many languages dividing two integers throws away the remainder, so 7 divided by 2 is 3 rather than 3.5. Python splits the two apart: one slash always gives a decimal, two slashes give the whole-number version. Knowing which one your language does is a classic source of quietly wrong numbers."],
 k:["Exact — no rounding error, unlike decimals.",
    "Integer division may truncate; check your language's rule.",
    "`%` gives the remainder — great for every-Nth-time logic.",
    "Large integers overflow in C, Java and Go; Python grows them forever."],
 x:{lang:"python", code:"print(7 / 2)    # 3.5   true division\nprint(7 // 2)   # 3     floor division\nprint(7 % 2)    # 1     remainder\nprint(2 ** 10)  # 1024  power"},
 r:["Floating-Point Number", "Modulo", "Data Type"]},

{t:"Floating-Point Number", a:"float", d:"A number with a decimal point, stored as an approximation — which is why 0.1 plus 0.2 is not quite 0.3.", l:"core", g:["basics","syntax","crash-course"],
 b:["Computers store decimals in binary, and some perfectly ordinary decimal numbers have no exact binary form — the same way one third has no exact decimal form. So 0.1 is stored as something microscopically close to 0.1, and those errors accumulate. Adding 0.1 and 0.2 really does print 0.30000000000000004.",
    "This is not a bug and it will not be fixed; it is what the hardware does. The practical rules are simple: never compare floats for exact equality, never store money as a float, and round only at the moment you show a number to a human."],
 k:["Decimals are approximations — tiny errors are normal.",
    "Compare with a tolerance, not with equals.",
    "Money belongs in integer cents or a Decimal type.",
    "Round for display, never in the middle of a calculation."],
 x:{lang:"python", code:"print(0.1 + 0.2)                     # 0.30000000000000004\nprint(0.1 + 0.2 == 0.3)              # False\nprint(round(0.1 + 0.2, 2) == 0.3)    # True\n\nfrom decimal import Decimal\nprint(Decimal(\"0.1\") + Decimal(\"0.2\"))   # 0.3"},
 r:["Integer", "Data Type", "Magic Number"]},

{t:"Boolean", a:"bool", d:"A value that is only ever true or false — the type every decision in code is built on.", l:"core", g:["basics","syntax","crash-course"],
 b:["Named after George Boole, who worked out the algebra of true and false in 1854, a century before there were computers to run it. Every if, every loop condition, every filter ultimately comes down to a boolean.",
    "Comparisons produce booleans, and three logical operators combine them: and needs both sides true, or needs one, not flips it. That is genuinely the whole system — every decision a program makes is built from those three."],
 k:["Exactly two values: true and false.",
    "Comparisons like `>` and `==` evaluate to booleans.",
    "`and`, `or`, `not` are the only three combinators you need.",
    "Name boolean variables as questions: `is_valid`, `has_access`."],
 x:{lang:"python", code:"age = 20\nis_adult = age >= 18       # True\nhas_ticket = False\n\nif is_adult and has_ticket:\n    print(\"come in\")\nelif is_adult and not has_ticket:\n    print(\"buy a ticket\")"},
 r:["Conditional", "Logical Operators", "Truthy and Falsy"]},

{t:"Null and Undefined", a:"None / nil / undefined", d:"A deliberate there-is-no-value-here — different from zero, empty text or false.", l:"core", g:["basics","syntax","crash-course"],
 b:["Null answers the question: what goes in the box when there is genuinely nothing to put in it? A user who has not set a nickname does not have an empty nickname — they have no nickname. Zero is a number. Empty text is text. Null is absence.",
    "Its inventor Tony Hoare called it his billion-dollar mistake, because forgetting to check for it is the most common crash in software: you ask for `user.email` when `user` is null and everything stops. Modern languages fight back with optional types, null-safe operators, and compilers that refuse to let you ignore the possibility."],
 k:["Absence of a value — not 0, not empty text, not false.",
    "Reading a property of null is the classic crash.",
    "`?.` returns nothing instead of exploding.",
    "JavaScript has two flavours: null (set to nothing) and undefined (never set)."],
 x:{lang:"javascript", code:"const user = { name: \"Sam\" };   // no address\n\n// user.address.city         -> TypeError, app dies\nconsole.log(user.address?.city);              // undefined, app lives\nconsole.log(user.address?.city ?? \"unknown\"); // \"unknown\""},
 r:["Optional Chaining", "Nullish Coalescing", "Exception"]},

{t:"Operator", d:"A symbol that does something to values — adds them, compares them, joins them, assigns them.", l:"core", g:["basics","syntax","crash-course"],
 b:["Operators are the punctuation of code. Plus, minus, times and divide do arithmetic. The comparison symbols ask questions. The logical symbols combine true and false. Equals assigns. They read left to right with the precedence rules you learned in school — multiplication before addition, brackets first.",
    "The confusing part is that the same symbol can mean different things depending on the types either side. Plus adds numbers, joins strings, and in some languages merges lists. This is called overloading, and it is why mixing a string and a number catches everyone at least once."],
 k:["Same symbol, different meaning by type — check your types.",
    "`=` assigns, `==` compares, `===` compares without converting.",
    "Precedence follows maths; brackets beat memorising the table.",
    "Boolean operators short-circuit — the right side may never run."],
 x:{lang:"javascript", code:"2 + 3       // 5\n\"2\" + 3     // \"23\"   string wins\n\"2\" * 3     // 6      * forces a number\n2 == \"2\"    // true   converts before comparing\n2 === \"2\"   // false  strict: types must match too"},
 r:["Assignment Operator", "Comparison Operators", "Logical Operators", "Modulo"]},

{t:"Assignment Operator", d:"The equals sign — it does not mean equals, it means put the right-hand value into the left-hand name.", l:"core", g:["basics","syntax","crash-course"],
 b:["`x = x + 1` is nonsense as maths and perfectly sensible as code: work out x plus 1, then store that back in x. Reading the equals sign out loud as becomes rather than equals clears up an enormous amount of early confusion.",
    "Most languages add shorthand for the common case of updating a variable using its own value, so `x += 1` means the same as `x = x + 1`, with matching forms for minus, times, divide and remainder. Comparison, when you actually want it, is a double or triple equals."],
 k:["The right side is calculated first, then stored on the left.",
    "`+=`, `-=`, `*=`, `/=` are shorthand for update-in-place.",
    "Using `=` where you meant `==` inside an if is a classic bug.",
    "Read it as becomes, never as equals."],
 x:{lang:"python", code:"total = 0\ntotal = total + 10   # long form\ntotal += 5           # same thing, shorter\ntotal *= 2           # 30\n\n# if total = 30:   <- SyntaxError in Python, silent bug in C"},
 r:["Variable", "Operator", "Comparison Operators"]},

{t:"Comparison Operators", d:"The symbols that ask a question about two values and answer true or false.", l:"core", g:["basics","syntax","crash-course"],
 b:["Double equals for equal, exclamation-equals for not equal, angle brackets for less and greater, with an added equals sign for or-equal. They always produce a boolean, which is why they live inside if statements and loop conditions.",
    "JavaScript adds a wrinkle: double equals quietly converts types before comparing, so zero equals empty string comes out true. Triple equals skips the conversion and compares type as well as value. Use triple equals unless you have a specific reason not to."],
 k:["Always returns true or false.",
    "In JavaScript prefer `===` and `!==` over `==` and `!=`.",
    "Comparing decimals for exact equality is unreliable.",
    "Chaining like `1 < x < 10` works in Python, not in most other languages."],
 x:{lang:"javascript", code:"0 == \"\"       // true   loose: converts both to 0\n0 === \"\"      // false  strict: number vs string\nNaN === NaN   // false  the one value unequal to itself\nObject.is(NaN, NaN)   // true"},
 r:["Operator", "Boolean", "Conditional"]},

{t:"Logical Operators", d:"And, or and not — the three ways to combine true/false answers into a bigger question.", l:"core", g:["basics","syntax","crash-course"],
 b:["And is true only when both sides are true. Or is true when at least one is. Not flips whatever you give it. Written as symbols in the C family and as words in Python; identical meaning.",
    "They short-circuit, which matters more than it sounds. In `user && user.name`, if user is null the second half is never evaluated — so this is a safe null check, not just a boolean expression. The same trick gives you the classic fallback idiom, a value or a default."],
 k:["And needs both; or needs one; not inverts.",
    "Short-circuit: the right side may never run.",
    "`a || fallback` is the classic default-value idiom.",
    "Use `??` instead of `||` when 0 or empty text are valid values."],
 x:{lang:"javascript", code:"const canEdit = isLoggedIn && isOwner;\nconst name = input || \"anonymous\";   // \"\" falls through\nconst count = input ?? 0;            // only null/undefined fall through\nif (!isLoggedIn) redirect(\"/login\");"},
 r:["Boolean", "Truthy and Falsy", "Nullish Coalescing", "Conditional"]},

{t:"Modulo", a:"%", d:"The remainder after division — the operator behind every-Nth-item, odd/even, and wrapping around a clock.", l:"core", g:["basics","syntax","crash-course"],
 b:["Seventeen modulo five is two, because five goes into seventeen three times with two left over. That is all it does, and it turns out to be enormously useful.",
    "Modulo two tests for even. Modulo ten fires every tenth iteration, which is perfect for progress logs. Adding then taking modulo twelve wraps a clock. Hash tables use modulo bucket-count to pick a bucket. Once you notice modulo you see it everywhere."],
 k:["Remainder, not division.",
    "`% 2` for odd and even; `% n` for every nth.",
    "Wraps values into a fixed range — clocks, buckets, circular buffers.",
    "Negative operands behave differently across languages; check first."],
 x:{lang:"python", code:"for i in range(1, 21):\n    if i % 15 == 0: print(\"FizzBuzz\")\n    elif i % 3 == 0: print(\"Fizz\")\n    elif i % 5 == 0: print(\"Buzz\")\n    else: print(i)"},
 r:["Integer", "Operator", "Expression", "Loop"]},

{t:"Expression", d:"A piece of code that produces a value.", l:"core", g:["basics","syntax","crash-course"],
 b:["Two plus two, a property lookup, a length check, a function call multiplied by a quantity — each of these evaluates down to a single value. If you can put it on the right of an equals sign, it is an expression.",
    "The distinction from a statement matters when you hit a syntax error you cannot explain. Some places in a language demand a value — a function argument, the right side of an assignment — and will reject a statement. That is why Python's if cannot go inside a function call but its ternary, which is an expression, can."],
 k:["Evaluates to a value; can nest inside other expressions.",
    "Anything you can assign to a variable is an expression.",
    "Statements do; expressions produce.",
    "Some languages, like Rust and Kotlin, make almost everything an expression."],
 r:["Statement", "Ternary Operator", "Return Value"]},

{t:"Statement", d:"A complete instruction that does something — one line of the recipe.", l:"core", g:["basics","syntax","crash-course"],
 b:["An assignment, a print, an if, a return, an import — these are commands, not values. A program is a sequence of statements executed top to bottom, with conditionals and loops changing which ones run and how often.",
    "In the C family, statements end with a semicolon; in Python, with a newline. Blocks — groups of statements that run together — are marked with braces in most languages and by indentation in Python."],
 k:["Does something; does not produce a value you can assign.",
    "Executed in order, top to bottom.",
    "Terminated by a semicolon or a newline, depending on the language.",
    "Blocks group statements with braces or indentation."],
 r:["Expression", "Indentation", "Conditional"]},

{t:"Conditional", a:"if / else", d:"The if-this-do-that fork in the road — how a program makes a decision.", l:"core", g:["basics","syntax","crash-course"],
 b:["An if takes a boolean and runs its block only when that boolean is true. Add else for the other case, and else-if to chain several tests. The first branch that matches wins and the rest are skipped, so order matters.",
    "Deeply nested conditionals are the classic readability killer. Two habits fix most of it: return early from the failure cases at the top of a function, and lift complicated conditions into a well-named boolean variable so the if reads like English."],
 k:["Runs a block only when a condition is true.",
    "First matching branch wins — order your tests carefully.",
    "Prefer guard clauses to deep nesting.",
    "Name complex conditions: `if is_eligible_for_refund:`"],
 x:{lang:"python", code:"# nested and hard to follow\nif user:\n    if user.active:\n        if user.credits > 0:\n            charge(user)\n\n# guard clauses -- same logic, readable\nif not user: return\nif not user.active: return\nif user.credits <= 0: return\ncharge(user)"},
 r:["Boolean", "Guard Clause", "Early Return", "Ternary Operator"]},

{t:"Ternary Operator", d:"A one-line if/else that produces a value instead of running a block.", l:"core", g:["basics","syntax","crash-course"],
 b:["Where an if statement chooses which code to run, the ternary chooses which value to hand back. Picking between the words item and items based on a count is shorter and clearer as one line than as four lines of if/else wrapped around an assignment.",
    "Python spells it in reading order — value, condition, alternative. Either way, keep it to one simple decision. Nested ternaries are legal and are almost always harder to read than the if/else they replaced."],
 k:["An expression, so it can go anywhere a value can.",
    "Perfect for small either/or values; terrible for logic.",
    "Never nest them — reach for if/else instead.",
    "Python's version reads value-first: `a if cond else b`."],
 x:{lang:"javascript", code:"const label = count === 1 ? \"item\" : \"items\";\nconst fee = isMember ? 0 : 4.99;\n\n// don't:\nconst t = a ? b ? \"x\" : \"y\" : c ? \"z\" : \"w\";"},
 r:["Conditional", "Expression", "Statement", "Boolean"]},

{t:"Truthy and Falsy", d:"Values that are not literally true or false but still count as one when tested in an if.", l:"core", g:["basics","syntax","crash-course"],
 b:["Most languages let you write if-items instead of if-items-has-length-greater-than-zero. To make that work they define which non-boolean values count as false. In JavaScript the falsy list is short and worth memorising: false, zero, empty string, null, undefined and NaN. Everything else — including the string \"0\", an empty array and an empty object — is truthy.",
    "Python's rule is different: empty containers are falsy, so an empty list, dict, string or zero are all false. Mixing the two mental models is a real source of bugs, particularly around zero and empty strings, where no value and a legitimate value that happens to be empty get confused."],
 k:["JavaScript falsy: false, 0, empty string, null, undefined, NaN.",
    "Empty array and empty object are truthy in JavaScript.",
    "Python falsy: False, 0, empty string, empty list/dict/set, None.",
    "`??` checks only null and undefined; `||` catches every falsy value."],
 x:{lang:"javascript", code:"if ([])  console.log(\"runs\");    // [] is truthy in JS\nif (\"0\") console.log(\"runs\");    // non-empty string\n\nlet qty = 0;\nqty || 10   // 10  -- wrong, 0 was a real answer\nqty ?? 10   // 0   -- right"},
 r:["Boolean", "Logical Operators", "Nullish Coalescing", "Null and Undefined"]},

{t:"Loop", d:"A block of code that repeats — once per item, or until a condition stops being true.", l:"core", g:["basics","syntax","crash-course"],
 b:["There are two shapes. A for loop runs once per item in a collection: for each user in users, send an email. A while loop repeats as long as a condition holds: while there are pages left, fetch the next one. Use for when you know the collection, while when you know the stopping rule.",
    "Two escape hatches exist inside any loop: break leaves immediately, continue skips to the next round. And the classic failure is the infinite loop — a while whose condition never becomes false because you forgot to change the thing it tests."],
 k:["For iterates a collection; while repeats on a condition.",
    "`break` exits; `continue` skips this iteration.",
    "A while that never changes its condition hangs forever.",
    "Modifying a list while looping over it produces skipped items."],
 x:{lang:"python", code:"for user in users:\n    if user.banned: continue      # skip this one\n    if quota_exhausted(): break   # stop entirely\n    send_email(user)\n\npage = 1\nwhile has_more(page):\n    fetch(page)\n    page += 1     # forget this line and it never ends"},
 r:["Iterator", "Zero-Based Indexing", "Off-by-One Error", "Nesting"]},

{t:"Nesting", d:"Putting one block inside another — a loop inside a loop, an if inside an if.", l:"core", g:["basics","syntax","crash-course"],
 b:["Nesting is how you express structure, and it is also how code becomes unreadable. Each level of nesting adds indentation and one more thing the reader has to hold in their head. Past three levels, most people stop being able to follow it.",
    "Nested loops also multiply work. A loop inside a loop over the same thousand-item list does a million iterations, not two thousand. That is the practical meaning of quadratic complexity, and it is the usual reason something that was fast in testing crawls in production."],
 k:["Each level costs the reader working memory — three is plenty.",
    "Extract the inner block into a named function to flatten it.",
    "Nested loops multiply: 1,000 times 1,000 is a million.",
    "Guard clauses and early returns are the standard flattening tools."],
 r:["Loop", "Conditional", "Guard Clause", "Big O Notation"]},

{t:"Function", d:"A named, reusable block of code: give it inputs, it does a job, it hands something back.", l:"core", g:["basics","syntax","crash-course"],
 b:["A function is the fundamental unit of reuse. You define it once and call it as many times as you like. The code inside runs, and return hands a value back to whoever called it. Nothing inside runs until someone calls it.",
    "The reason functions matter is not typing less. It is that a well-named function replaces five lines you have to read with one line you can trust. Calculate-shipping tells the reader what happens without making them care how. Keep each one doing a single thing, and short enough to see whole."],
 k:["Define once, call many times.",
    "Inputs are parameters; return sends a value back.",
    "One job per function; the name should say what that job is.",
    "No return means it hands back null or undefined implicitly."],
 x:{lang:"python", code:"def total(price, qty, discount=0):\n    \"\"\"Line total after an optional discount.\"\"\"\n    subtotal = price * qty\n    return subtotal * (1 - discount)\n\nprint(total(9.99, 3))         # 29.97\nprint(total(9.99, 3, 0.1))    # 26.973"},
 r:["Parameter", "Argument", "Return Value", "Method", "Lambda Function"]},

{t:"Parameter", d:"The named slot in a function definition — a label for a value the function expects to be given.", l:"core", g:["basics","syntax","crash-course"],
 b:["In a definition like greet-of-name, name is a parameter. It does not exist until the function is called; it is a promise that says whoever calls me must supply something, and inside here I will call it name.",
    "Parameters can have defaults, which makes them optional. Beware of using a list or dictionary as a default in Python — it is created once and shared between every call, a famous and genuinely surprising bug."],
 k:["Declared in the definition; a placeholder, not a value.",
    "Defaults make a parameter optional.",
    "Never use a mutable default like an empty list in Python — use None.",
    "Keyword arguments make calls readable: `send(to=x, subject=y)`."],
 x:{lang:"python", code:"def add_item(item, basket=None):    # correct\n    basket = basket or []\n    basket.append(item)\n    return basket\n\ndef broken(item, basket=[]):        # shared between calls!\n    basket.append(item)\n    return basket"},
 r:["Argument", "Function", "Return Value"]},

{t:"Argument", d:"The actual value you pass in when you call a function.", l:"core", g:["basics","syntax","crash-course"],
 b:["Parameters are the slots; arguments are what you drop into them. Calling greet with the text Aryan passes that argument into the parameter called name. People use the two words interchangeably in conversation and it rarely matters, but the distinction makes error messages much easier to read.",
    "Arguments can be positional, matched by order, or keyword, matched by name. Once a call has more than two or three inputs, keyword arguments are worth the extra typing: four bare values in a row are unreadable, four named ones are obvious."],
 k:["The real value; the parameter is the slot it lands in.",
    "Positional arguments are matched by order — easy to get wrong.",
    "Keyword arguments document the call site for free.",
    "`*args` and `**kwargs` collect any extras in Python."],
 r:["Parameter", "Function", "Return Value", "Method"]},

{t:"Return Value", d:"What a function hands back to whoever called it.", l:"core", g:["basics","syntax","crash-course"],
 b:["Return does two things at once: it sends a value back, and it exits the function immediately. Any code after it in that function never runs, which is exactly what makes guard clauses work.",
    "A function with no return still returns something — None in Python, undefined in JavaScript. This trips people up constantly: assigning the result of a sort gives you nothing, because sorting reorders the list in place and returns nothing. The sorted version is the one that returns a new list."],
 k:["Sends a value back and exits the function on the spot.",
    "No return means None or undefined, not nothing happened.",
    "In-place methods usually return nothing — check the docs.",
    "Return early for failure cases; keep the happy path unindented."],
 x:{lang:"python", code:"nums = [3, 1, 2]\nprint(nums.sort())      # None   -- sorts in place\nprint(nums)             # [1, 2, 3]\nprint(sorted([3,1,2]))  # [1, 2, 3]  -- returns a new list"},
 r:["Function", "Early Return", "Guard Clause"]},

{t:"Early Return", d:"Leaving a function as soon as you know the answer, instead of nesting the rest of the code inside an else.", l:"core", g:["basics","practice","crash-course"],
 b:["The instinct is to write one big if around everything that should happen and an else for the failure. The result is code that drifts further right with every rule you add. Early return inverts it: handle each bad case at the top, return, and let the real work sit flat at the bottom.",
    "The payoff is that the interesting logic is never buried three levels deep, and each rejection reason sits next to the condition that caused it. It is one of the cheapest readability upgrades available."],
 k:["Handle failures first, then let the main path run unindented.",
    "Each early return pairs a reason with its check.",
    "Keeps nesting shallow as rules accumulate.",
    "Also known as a guard clause."],
 r:["Guard Clause", "Return Value", "Conditional", "Happy Path"]},

{t:"Guard Clause", d:"A check at the top of a function that bails out immediately if the input is not usable.", l:"core", g:["basics","practice","crash-course"],
 b:["One line, at the top, before anything else: if there is no user, return. The rest of the function can then assume a user exists, which means no further null checks and no extra indentation.",
    "Guard clauses turn a function's preconditions into a visible checklist. A reader can see in five seconds what has to be true for the real work to happen, and each guard can carry a specific error message instead of one vague failure at the end."],
 k:["States a precondition and exits if it fails.",
    "Lets the rest of the function assume valid input.",
    "Pairs each rejection with a specific reason.",
    "Read the top of a function to learn its contract."],
 x:{lang:"javascript", code:"function applyDiscount(order, code) {\n  if (!order) return null;\n  if (!code) return order;\n  if (order.total <= 0) return order;\n  if (isExpired(code)) throw new Error(\"Code expired\");\n\n  return { ...order, total: order.total * 0.9 };\n}"},
 r:["Early Return", "Conditional", "Edge Case"]},

{t:"Method", d:"A function that belongs to an object and usually acts on that object's own data.", l:"core", g:["basics","syntax","crash-course"],
 b:["When you write text-dot-upper, upper is a method. It is a function, but it lives on the string and knows which string it was called on. That is the only real difference: a method arrives with a built-in first argument, the thing it belongs to, spelled self in Python and this in JavaScript and Java.",
    "Methods are how objects expose what they can do. A list can append and sort; a date can format itself; a database connection can execute a query. Reading unfamiliar code, the dot is your clue: the thing on the left is the data, the thing on the right is a capability it offers."],
 k:["A function attached to an object, called with a dot.",
    "Receives the object itself as a hidden first argument.",
    "`self` in Python, `this` in JavaScript, Java and C#.",
    "Some methods change the object; some return a new one — check which."],
 x:{lang:"python", code:"class Cart:\n    def __init__(self):\n        self.items = []\n\n    def add(self, item):        # method\n        self.items.append(item)\n        return self\n\ncart = Cart()\ncart.add(\"book\").add(\"pen\")\nprint(len(cart.items))   # 2"},
 r:["Function", "Property", "Instance", "Constructor"]},

{t:"Property", d:"A named piece of data attached to an object — the nouns, where methods are the verbs.", l:"core", g:["basics","syntax","crash-course"],
 b:["A user object might have properties name, email and created-at. You reach them with a dot, the same syntax as methods, but you read and write them rather than calling them. If it has brackets after it, it is a method; if not, it is a property.",
    "Some languages let a property look like plain data while quietly running code behind the scenes — Python's property decorator and JavaScript getters do exactly this. That is handy for computed values like a full name assembled from first and last."],
 k:["Data on an object, reached with a dot and no brackets.",
    "Methods are called; properties are read and assigned.",
    "Getters can compute a property on the fly.",
    "Reading a property of null is the most common runtime crash."],
 r:["Method", "Instance", "Null and Undefined", "Key-Value Pair"]},

{t:"Instance", d:"One actual object built from a class — the cake, where the class is the recipe.", l:"core", g:["basics","syntax","crash-course"],
 b:["A class describes what every user will have: a name, an email, a way to reset a password. An instance is one specific user, with a real name and a real email, sitting in memory. You can make thousands of instances from one class, and each keeps its own copy of the data.",
    "This is why classes are worth the ceremony: you write the shape and the behaviour once, then stamp out as many independent copies as you need. Creating one is called instantiating, and it is what the new keyword or a call to the class name does."],
 k:["The class is the blueprint; the instance is the built thing.",
    "Each instance carries its own data, shares the class's methods.",
    "Created with `new ClassName()` or by calling the class in Python.",
    "Instantiating means building an instance."],
 x:{lang:"python", code:"class User:\n    def __init__(self, name):\n        self.name = name\n\na = User(\"Ada\")     # one instance\nb = User(\"Grace\")   # another, independent\nprint(a.name, b.name)   # Ada Grace"},
 r:["Constructor", "Method", "Property", "Class"]},

{t:"Constructor", d:"The special function that runs when an object is created, to set up its starting data.", l:"core", g:["basics","syntax","crash-course"],
 b:["Called dunder-init in Python and constructor in JavaScript and Java, this is where you take the values passed in and store them on the new object. It is the only place many objects ever get their identity.",
    "The useful habit is to make the constructor cheap and boring: assign fields, validate inputs, and stop. Network calls, file reads and heavy computation inside a constructor make objects slow to create and almost impossible to test."],
 k:["Runs automatically when an instance is created.",
    "Its job is to store the starting values on the new object.",
    "Keep it cheap — no network calls or heavy work.",
    "`__init__` in Python, `constructor` in JavaScript and Java."],
 r:["Instance", "Method", "Class"]},

{t:"Module", d:"One file of code you can pull into another file, so related things live together and can be reused.", l:"core", g:["basics","syntax","crash-course"],
 b:["Once a program grows past a few hundred lines, it stops fitting in one file. A module is the unit you split it into: a file containing related functions, classes and constants. Other files import what they need by name.",
    "Modules give you namespacing for free — two modules can each have a function called parse without colliding, because callers say which one they mean. They are also the boundary along which you can test, replace or delete a piece of a system."],
 k:["Usually one file; the natural unit of organisation.",
    "Import brings specific names into the current file.",
    "Keeps names from colliding between parts of a program.",
    "A package is a folder of modules."],
 x:{lang:"python", code:"# pricing.py\nTAX = 0.18\ndef with_tax(amount):\n    return amount * (1 + TAX)\n\n# app.py\nfrom pricing import with_tax\nprint(with_tax(100))    # 118.0"},
 r:["Import", "Namespace", "Package", "Library"]},

{t:"Import", d:"The line at the top of a file that pulls in code from somewhere else so you can use it.", l:"core", g:["basics","syntax","crash-course"],
 b:["Nothing in a file can see anything outside it until you import it. That is why every real file starts with a small block of imports: the standard library, third-party packages, then your own modules. Most languages and linters like that order, with a blank line between groups.",
    "Import errors are among the first errors everyone meets. Module-not-found usually means the package is not installed or the virtual environment is not active. Circular import means two files import each other, and the fix is almost always to pull the shared piece into a third module."],
 k:["Makes outside code visible inside this file.",
    "Order: standard library, third-party, then local.",
    "Module-not-found usually means not installed, or wrong environment.",
    "Circular imports signal that a shared piece needs its own module."],
 x:{lang:"python", code:"import os                       # whole module\nfrom pathlib import Path        # one name from it\nimport numpy as np              # renamed for brevity\nfrom .models import User        # relative, same package"},
 r:["Module", "Namespace", "Dependency", "Virtual Environment"]},

{t:"Namespace", d:"A container for names, so two different things can share a label without clashing.", l:"core", g:["basics","syntax","crash-course"],
 b:["Every module, class and function creates a namespace. That is why numpy's array and your own array can coexist: one is np-dot-array, the other is just array. The dot is the separator between namespace and name.",
    "The practical advice that follows is to avoid star-imports, which dump every name from a module straight into yours and make it impossible to tell where anything came from. Importing the module and using the prefix costs a few characters and saves real confusion."],
 k:["A named scope that keeps identifiers from colliding.",
    "The dot navigates from namespace to name.",
    "Avoid star-imports — they hide where a name came from.",
    "Modules, classes and functions each create one."],
 r:["Module", "Import", "Scope"]},

{t:"Comment", d:"A note to humans inside the code, which the computer ignores completely.", l:"core", g:["basics","syntax","crash-course"],
 b:["A hash in Python, two slashes in the C family. Everything after it on that line is invisible to the machine. Comments are for the reader, including the version of you that comes back in six months.",
    "The rule worth internalising is: comment the why, not the what. Code already says what it does. A comment that restates the line is noise that will drift out of date. A comment explaining why this retries three times, or which bug this odd-looking check works around, is worth its weight in gold."],
 k:["Ignored by the computer, written entirely for people.",
    "Explain why, not what — the code already says what.",
    "A comment that contradicts the code is worse than no comment.",
    "Commented-out code should be deleted; version control remembers it."],
 x:{lang:"python", code:"# BAD: adds one to i\ni += 1\n\n# GOOD: the vendor API is 1-indexed, ours is 0-indexed\ni += 1"},
 r:["Docstring", "Magic Number", "Legacy Code"]},

{t:"Docstring", d:"A short description written inside a function, class or module, which tools and editors can read back to you.", l:"core", g:["basics","syntax","crash-course"],
 b:["Unlike a comment, a docstring is part of the object at runtime. Python stores it as dunder-doc, help reads it, editors show it on hover, and documentation generators turn a codebase full of them into a website.",
    "A good docstring answers three questions in a few lines: what does this do, what does it expect, and what does it give back. Anything about how it works belongs in comments inside the body instead."],
 k:["A string at the top of a function, class or module.",
    "Available at runtime — powers help, hovers and generated docs.",
    "Cover purpose, inputs and outputs; skip implementation detail.",
    "Triple-quoted in Python; JSDoc block comments in JavaScript."],
 x:{lang:"python", code:"def chunk(text, size=500):\n    \"\"\"Split text into pieces of at most `size` characters.\n\n    Args:\n        text: the source text.\n        size: max characters per chunk.\n    Returns:\n        A list of strings.\n    \"\"\"\n    return [text[i:i+size] for i in range(0, len(text), size)]"},
 r:["Comment", "Function", "Type Hint"]},

{t:"Indentation", d:"The spaces at the start of a line that show which block a statement belongs to.", l:"core", g:["basics","syntax","crash-course"],
 b:["In most languages indentation is only a courtesy to readers; braces decide the real structure. In Python it is the structure — an indented line is inside the block above it, and getting it wrong changes what your program does or stops it running altogether.",
    "The universal advice is to pick one style and let a formatter enforce it. Four spaces is the Python standard, two is common in JavaScript. Mixing tabs and spaces produces errors that are invisible on screen, which is exactly the kind of bug worth automating away."],
 k:["In Python it defines blocks; elsewhere it is convention.",
    "Never mix tabs and spaces in the same file.",
    "Four spaces in Python, two in most JavaScript style guides.",
    "Let a formatter decide, so nobody argues about it."],
 r:["Statement", "Code Formatter", "Nesting"]},

{t:"Zero-Based Indexing", d:"The rule that the first item in a list is at position 0, not 1.", l:"core", g:["basics","syntax","crash-course"],
 b:["It looks like an arbitrary annoyance and it is not: an index is an offset from the start of the block of memory. The first item is zero steps from the start, the second is one step, and so on. Almost every language inherited this from C.",
    "The consequence to burn into memory is that a list of ten items has valid indexes 0 through 9, and asking for index 10 is an error. Negative indexes in Python count from the end, so minus one is the last item — a genuinely useful convenience once you trust it."],
 k:["First item is index 0; last is length minus one.",
    "An index is an offset, not a count.",
    "Asking for index equal to the length is the classic crash.",
    "Python's negative indexes count backwards from the end."],
 x:{lang:"python", code:"items = [\"a\", \"b\", \"c\"]\nprint(items[0])    # a   first\nprint(items[2])    # c   last\nprint(items[-1])   # c   last, the easy way\n# items[3]         # IndexError"},
 r:["Off-by-One Error", "Slicing", "Loop"]},

{t:"Off-by-One Error", d:"Being wrong by exactly one — looping one time too many, or missing the last item.", l:"core", g:["basics","bugs","crash-course"],
 b:["It is the most common arithmetic bug in software, and it comes from the collision between how humans count and how computers index. A fence with ten posts has nine gaps. A list with ten items has indexes 0 to 9. Slices usually include the start and exclude the end.",
    "The defences are simple: prefer looping directly over a collection rather than over a range of numbers, use built-in helpers like enumerate, and when you do write a boundary, test it with an empty list and a one-item list. Those two cases catch nearly every off-by-one."],
 k:["Off by exactly one — usually at the first or last item.",
    "Ranges and slices are typically start-inclusive, end-exclusive.",
    "Iterate the collection directly instead of indexing where you can.",
    "Test with zero items and one item to expose it."],
 x:{lang:"python", code:"items = [\"a\", \"b\", \"c\"]\n\nfor i in range(len(items) - 1):   # misses \"c\"\n    print(items[i])\n\nfor item in items:                # correct and clearer\n    print(item)"},
 r:["Zero-Based Indexing", "Loop", "Edge Case", "Slicing"]},

{t:"Key-Value Pair", d:"A label attached to a value — the basic unit of a dictionary, a JSON object, and most configuration.", l:"core", g:["basics","syntax","crash-course"],
 b:["Instead of remembering that position three holds the email address, you ask for the value under the key email. That is the whole idea, and it is everywhere: HTTP headers, environment variables, JSON payloads, database rows, function keyword arguments.",
    "Lookup by key is close to instantaneous no matter how many pairs there are, because a hash function jumps straight to the right slot. That is why dictionaries are the default choice whenever you need to find something by name rather than by position."],
 k:["A name pointing to a value; the key is unique.",
    "Lookup by key is effectively constant time.",
    "The backbone of JSON, config files, headers and query strings.",
    "Keys are usually strings; values can be anything, including more pairs."],
 x:{lang:"javascript", code:"const user = { id: 7, name: \"Ada\", admin: true };\n\nuser.name          // \"Ada\"\nuser[\"name\"]       // same thing\nObject.keys(user)  // [\"id\", \"name\", \"admin\"]\nuser.email ?? \"—\"  // missing keys give undefined"},
 r:["Dictionary", "JSON", "Hash Table", "Property"]},

{t:"Dictionary", a:"dict / map / object", d:"A collection of key-value pairs you look things up in by name.", l:"core", g:["basics","syntax","crash-course"],
 b:["A list answers what is at position 3. A dictionary answers what is stored under the name email. Different languages call it dict, map, hash, object or associative array — the same structure with different clothes.",
    "The one rule beginners trip on: asking for a key that does not exist. Python raises a KeyError, JavaScript quietly gives you undefined. Both have a safe form — get with a default in Python, nullish coalescing in JavaScript — and using it is nearly always the right call for data you did not create."],
 k:["Look up by key, not by position.",
    "Missing key: exception in Python, undefined in JavaScript.",
    "Use the safe accessor with a default for external data.",
    "Since Python 3.7 dictionaries remember insertion order."],
 x:{lang:"python", code:"config = {\"host\": \"localhost\", \"port\": 8000}\n\nprint(config[\"host\"])            # localhost\nprint(config.get(\"debug\", False)) # False, no crash\n# print(config[\"debug\"])         # KeyError\n\nfor key, value in config.items():\n    print(key, \"=\", value)"},
 r:["Key-Value Pair", "Hash Table", "JSON", "Set"]},

{t:"Iterator", d:"Something that hands you one item at a time, on demand, instead of building the whole list up front.", l:"core", g:["basics","syntax","crash-course"],
 b:["When you loop over a file, you are not loading a two-gigabyte file into memory; you are asking an iterator for the next line, over and over, until it says there are none left. That is the entire protocol: give me the next thing, or tell me you are done.",
    "This is why iterators matter for large data. A range of ten million numbers costs almost nothing until you actually iterate it. The trade-off is that most iterators are single-use — once consumed, they are empty, and looping a second time silently does nothing."],
 k:["Produces items lazily, one at a time.",
    "Constant memory regardless of how many items there are.",
    "Usually single-use — a second loop sees nothing.",
    "Generators are the easy way to write your own."],
 x:{lang:"python", code:"squares = (n * n for n in range(10_000_000))   # nothing computed yet\nprint(next(squares))   # 0\nprint(next(squares))   # 1\n\nwith open(\"big.log\") as f:\n    for line in f:     # one line at a time\n        process(line)"},
 r:["Loop", "List Comprehension", "Slicing"]},

{t:"Slicing", d:"Taking a chunk out of a list or string by writing a start and an end position.", l:"core", g:["basics","syntax","crash-course"],
 b:["The notation is start-colon-end, and the end is not included. So zero-colon-three gives you the first three items. Leaving a side blank means all the way to that edge, which is why colon-alone copies the whole thing.",
    "Once the exclusive end clicks, slices become pleasant: the length of a slice is simply end minus start, and consecutive slices join up perfectly with no overlap and no gap. Python adds a third number for a step, and a step of minus one reverses."],
 k:["Start is included, end is excluded.",
    "Length of a slice equals end minus start.",
    "Omit a side to run to the beginning or the end.",
    "In Python, `[::-1]` reverses a string or list."],
 x:{lang:"python", code:"s = \"engineering\"\nprint(s[0:3])    # eng\nprint(s[:3])     # eng\nprint(s[3:])     # ineering\nprint(s[-4:])    # ring\nprint(s[::-1])   # gnireenigne"},
 r:["Zero-Based Indexing", "String", "Off-by-One Error"]},

{t:"List Comprehension", d:"A one-line way to build a new list from an old one, with optional filtering.", l:"core", g:["basics","syntax","crash-course"],
 b:["Four lines that create an empty list, loop, test a condition and append become one line that reads almost like set-builder notation from maths: this expression, for each item, where the condition holds.",
    "It is idiomatic Python and worth learning to read even if you write loops. The limit is complexity — once you need two conditions and a nested loop, the comprehension stops being clearer than the loop it replaced, and a plain for loop is the better choice."],
 k:["Expression, then for, then an optional if.",
    "Replaces the create-loop-append pattern.",
    "Swap the brackets for parentheses to get a lazy generator.",
    "If it needs a comment to read, write the loop instead."],
 x:{lang:"python", code:"# the long way\nnames = []\nfor u in users:\n    if u.active:\n        names.append(u.name.title())\n\n# the same thing\nnames = [u.name.title() for u in users if u.active]"},
 r:["Loop", "Iterator", "Lambda Function"]},

{t:"Lambda Function", a:"anonymous function", d:"A tiny function with no name, written inline where it is needed.", l:"core", g:["basics","syntax","crash-course"],
 b:["When a function is one expression long and used in exactly one place, giving it a name is ceremony. A lambda lets you write it where it is used — most often as the sort key, filter test or map transform being handed to another function.",
    "In JavaScript the arrow function has largely taken this role and is used for far more than one-liners. In Python the convention is stricter: if it does not fit comfortably on one line, define a real function with a real name."],
 k:["A function value with no name, defined inline.",
    "Most common as a sort key, filter test or map transform.",
    "Python lambdas are limited to a single expression.",
    "If it needs a name to be understood, give it one."],
 x:{lang:"python", code:"users.sort(key=lambda u: u.created_at)\nadults = list(filter(lambda u: u.age >= 18, users))\n\n# often clearer as a comprehension\nadults = [u for u in users if u.age >= 18]"},
 r:["Function", "Arrow Function", "Higher-Order Function", "List Comprehension"]},

{t:"Arrow Function", d:"JavaScript's short function syntax — and it also changes what `this` means inside it.", l:"core", g:["basics","syntax","javascript","crash-course"],
 b:["An arrow between the parameters and the body replaces the function keyword. With a single expression and no braces, the value is returned automatically, which makes callbacks dramatically shorter to read.",
    "The part that is not just cosmetic: arrow functions do not get their own `this`. They inherit it from wherever they were written. That is precisely why they fixed the old bug where `this` mysteriously became undefined inside a callback — and also why they are the wrong choice for object methods that need their own `this`."],
 k:["`x => x * 2` returns automatically with no braces.",
    "Inherits `this` from the surrounding scope.",
    "Ideal for callbacks; wrong for object methods needing their own `this`.",
    "Cannot be used as a constructor."],
 x:{lang:"javascript", code:"const double = x => x * 2;\nconst add = (a, b) => a + b;\nconst make = id => ({ id });        // wrap object literals in ()\n\nusers.filter(u => u.active).map(u => u.name);"},
 r:["Lambda Function", "Function", "Higher-Order Function"]},

{t:"Type Hint", a:"type annotation", d:"A note in the code saying what type a value is meant to be — checked by tools, not by the running program.", l:"core", g:["basics","syntax","crash-course"],
 b:["Python and JavaScript let you run anything; type hints add the safety net back without giving up that flexibility. Writing that a function takes a string and returns a list of dicts lets editors autocomplete accurately, lets a checker catch mistakes before you run anything, and documents intent better than a comment.",
    "In Python the hints are ignored at runtime unless a library like Pydantic enforces them. TypeScript goes further: it type-checks at build time and then strips the annotations out, so what actually runs in the browser is plain JavaScript."],
 k:["Documents intent and powers autocomplete and static checking.",
    "Python ignores them at runtime; a checker like mypy reads them.",
    "TypeScript checks at build time, then erases them.",
    "Adding hints to public function signatures gives most of the benefit."],
 x:{lang:"python", code:"def chunk(text: str, size: int = 500) -> list[str]:\n    return [text[i:i+size] for i in range(0, len(text), size)]\n\nfrom typing import Optional\ndef find(uid: int) -> Optional[dict]:\n    ...   # may return a dict or None"},
 r:["Data Type", "Docstring", "Linter"]},

{t:"String Interpolation", a:"f-string / template literal", d:"Dropping a variable straight into a piece of text instead of gluing strings together.", l:"core", g:["basics","syntax","crash-course"],
 b:["Rather than joining fragments with plus signs and remembering to convert numbers, you write the text once and put the expressions inline in braces. Python calls these f-strings; JavaScript uses backticks and dollar-brace.",
    "Beyond readability, this matters for safety: never build a SQL query or a shell command by pasting user input into a string, no matter how convenient the syntax is. Use parameterised queries. Interpolation is for messages you show, not for commands you execute."],
 k:["Put expressions inline instead of concatenating fragments.",
    "Python: `f\"Hi {name}\"`. JavaScript: backticks with `${name}`.",
    "Handles number-to-text conversion for you.",
    "Never interpolate user input into SQL or shell commands."],
 x:{lang:"python", code:"name, total = \"Ada\", 1234.5\n\nprint(\"Hi \" + name + \", you owe \" + str(total))   # clunky\nprint(f\"Hi {name}, you owe {total:,.2f}\")        # Hi Ada, you owe 1,234.50\nprint(f\"{total = }\")                             # total = 1234.5  (debug)"},
 r:["String", "String Concatenation", "SQL Injection"]},

{t:"String Concatenation", d:"Joining two pieces of text end to end.", l:"core", g:["basics","syntax","crash-course"],
 b:["The plus sign does it in most languages. It is the simplest possible string operation and it hides one real performance trap: because strings are immutable, every concatenation builds a brand new string. Doing that inside a loop over ten thousand items copies the whole growing string ten thousand times.",
    "The fix in every language is the same shape: collect the pieces in a list and join them once at the end. For a handful of fragments it makes no difference; for a loop, it is the difference between instant and noticeably slow."],
 k:["Plus joins text; both sides must actually be text.",
    "Each concatenation allocates a new string.",
    "In a loop, collect pieces and `join` once at the end.",
    "For readability, prefer interpolation over long plus chains."],
 x:{lang:"python", code:"# slow for large loops\nout = \"\"\nfor row in rows:\n    out += row + \"\\n\"\n\n# fast and clearer\nout = \"\\n\".join(rows)"},
 r:["String", "String Interpolation", "Expression", "Operator"]},

{t:"Escape Character", d:"A backslash that tells the language the next character is data, not punctuation.", l:"core", g:["basics","syntax","crash-course"],
 b:["To put a double quote inside a double-quoted string, you have to say it is not the end of the string — that is a backslash-quote. The same mechanism produces newline, tab and the literal backslash itself.",
    "This gets confusing when several layers each want their own escaping, most famously in regular expressions written inside string literals: the regex wants a backslash, the string wants a backslash to make one, and you end up with four in a row. Raw strings, marked with an r in Python, turn off string-level escaping and remove one whole layer of pain."],
 k:["`\\n` newline, `\\t` tab, `\\\\` a literal backslash, `\\\"` a quote.",
    "Raw strings turn off escaping — ideal for regex and Windows paths.",
    "Switching quote style often avoids escaping entirely.",
    "Nested escaping is a sign you should be using a library, not string surgery."],
 x:{lang:"python", code:"print(\"She said \\\"hi\\\"\")     # She said \"hi\"\nprint('She said \"hi\"')       # easier: swap quote style\nprint(\"line1\\nline2\")        # two lines\nprint(r\"C:\\Users\\new\")       # raw: backslashes stay put"},
 r:["String", "Regular Expression", "Escaping", "Encoding"]},

{t:"Optional Chaining", a:"?.", d:"A question mark before a dot that returns nothing instead of crashing when the thing on the left is missing.", l:"core", g:["basics","syntax","javascript","crash-course"],
 b:["Reading a property of null is the single most common runtime crash in JavaScript. Optional chaining short-circuits the whole expression the moment it meets null or undefined and hands back undefined, so the app keeps running.",
    "It works on method calls and index access too. The one warning is not to sprinkle it everywhere: if a value should always exist, a crash is useful information. Use it where absence is genuinely expected — optional API fields, data still loading — not to silence errors you have not understood."],
 k:["Returns undefined instead of throwing when the left side is nullish.",
    "Works on properties, calls and index access.",
    "Pairs naturally with `??` to supply a default.",
    "Do not use it to hide values that should never be missing."],
 x:{lang:"javascript", code:"user?.profile?.avatar?.url ?? \"/default.png\"\napi.onReady?.();          // call only if it exists\nrows?.[0]?.name;          // safe index access"},
 r:["Null and Undefined", "Nullish Coalescing", "Truthy and Falsy"]},

{t:"Nullish Coalescing", a:"??", d:"A default-value operator that only kicks in for null and undefined — not for zero or empty text.", l:"core", g:["basics","syntax","javascript","crash-course"],
 b:["The old default idiom used or, which treats every falsy value as missing. That quietly breaks the moment zero or an empty string is a legitimate answer: a quantity of zero becomes the default ten, a deliberately blank note becomes placeholder text.",
    "The two-question-mark operator fixes exactly that. It asks only one question — is this null or undefined? — and passes everything else through untouched, including zero, empty strings and false."],
 k:["Falls back only for null and undefined.",
    "`||` also falls back for 0, empty string and false — usually a bug.",
    "Pairs with optional chaining for safe reads with a default.",
    "Reach for `??` by default and use `||` deliberately."],
 x:{lang:"javascript", code:"const qty = input.qty ?? 1;      // 0 stays 0\nconst qtyBad = input.qty || 1;   // 0 becomes 1  (bug)\nconst note = input.note ?? \"\";   // \"\" stays \"\""},
 r:["Null and Undefined", "Logical Operators", "Truthy and Falsy", "Optional Chaining"]},

{t:"Spread Operator", a:"...", d:"Three dots that unpack a list or object into another one — the standard way to copy without mutating.", l:"core", g:["basics","syntax","javascript","crash-course"],
 b:["Spreading pours the contents of one array or object into a new one, so you get a copy with your changes applied and the original untouched. That is the backbone of state updates in React and of immutable data handling generally.",
    "The same three dots do the opposite job in a function's parameters, where they gather any extra arguments into an array — there it is called rest. One important caveat: the copy is shallow. Nested objects are still shared with the original, so changing a nested field changes both."],
 k:["Copies an array or object into a new one.",
    "Later keys win, which makes overriding a field trivial.",
    "In a parameter list the same syntax gathers extras (rest).",
    "The copy is shallow — nested objects are still shared."],
 x:{lang:"javascript", code:"const updated = { ...user, name: \"New\" };   // copy + override\nconst all = [...a, ...b];                   // merge arrays\n\nfunction log(first, ...others) {            // rest\n  console.log(first, others.length);\n}"},
 r:["Immutability", "Key-Value Pair", "Argument"]},

{t:"Naming Conventions", d:"The agreed styles for writing multi-word names — camelCase, snake_case, PascalCase, kebab-case.", l:"core", g:["basics","practice","crash-course"],
 b:["Each community settled on its own: Python uses snake_case for functions and variables and PascalCase for classes; JavaScript uses camelCase and PascalCase; CSS and URLs use kebab-case; constants are SCREAMING_SNAKE_CASE nearly everywhere. Files and folders vary by ecosystem.",
    "None of it is technically necessary and all of it is worth following, because the style itself carries information. Seeing PascalCase tells a reader this is a class or component before they read a single character of the name."],
 k:["snake_case: Python variables and functions.",
    "camelCase: JavaScript variables and functions.",
    "PascalCase: classes and React components in both.",
    "SCREAMING_SNAKE_CASE: constants. kebab-case: URLs and CSS."],
 x:{lang:"python", code:"MAX_RETRIES = 3          # constant\nclass PaymentGateway:    # class\n    def charge_card(self, card_number):   # function, variable\n        ..."},
 r:["Constant", "Variable", "Code Formatter", "Magic Number"]},

{t:"Magic Number", d:"An unexplained literal value sitting in the middle of code, with no clue where it came from.", l:"core", g:["basics","practice","crash-course"],
 b:["Seeing 86400 in a line of code, a reader has to stop and work out that it is the number of seconds in a day. Seeing 0.18 they have to guess whether it is a tax rate, a discount or a threshold. The number is not wrong — it is just undocumented.",
    "The fix takes ten seconds: give it a name at the top of the file. The name explains the value, the single definition means you change it in one place, and searching for the name finds every use — none of which is true of a bare number."],
 k:["An unexplained literal is a comment that was never written.",
    "Name it as a constant at the top of the module.",
    "One definition means one place to change it.",
    "Applies to strings too — repeated status text belongs in an enum."],
 x:{lang:"python", code:"# before\nif elapsed > 86400: expire(session)\n\n# after\nSECONDS_PER_DAY = 86_400\nif elapsed > SECONDS_PER_DAY: expire(session)"},
 r:["Constant", "Comment", "Naming Conventions", "Enum"]},

{t:"Enum", a:"enumeration", d:"A fixed set of named options — the right type for a value that can only be one of a few things.", l:"core", g:["basics","syntax","crash-course"],
 b:["An order status is pending, paid, shipped or cancelled — never anything else. Storing that as a loose string invites typos that no tool can catch: shiped sails straight through and fails silently later.",
    "An enum makes the set explicit. Editors autocomplete the options, type checkers reject anything outside the set, and the list of valid values lives in one obvious place instead of being scattered through comparisons across the codebase."],
 k:["A named, closed set of possible values.",
    "Turns typo bugs into errors your tools catch.",
    "One place to see every valid option.",
    "Python has `enum.Enum`; TypeScript has enums and string unions."],
 x:{lang:"python", code:"from enum import Enum\n\nclass Status(Enum):\n    PENDING = \"pending\"\n    PAID = \"paid\"\n    SHIPPED = \"shipped\"\n\nif order.status is Status.PAID:\n    ship(order)"},
 r:["Constant", "Magic Number", "Data Type"]},

{t:"Pass by Value vs Reference", d:"Whether a function receives an isolated copy of data, or a direct pointer to the original object in memory.", l:"core", g:["basics","cs","crash-course"],
 b:["When you pass a primitive value (like a number or boolean) into a function, the language makes a fresh copy in a new box. If the function changes that number, the caller's original variable is completely untouched — this is pass by value.",
    "When you pass a complex object or list, the function receives a copy of the pointer pointing to the same shared object on the heap. If the function modifies a property or appends an item to that object, the change is immediately visible to the caller. Forgetting this distinction is the number one cause of accidental data mutation bugs."],
 k:["Primitives (numbers, booleans) are passed by value as isolated copies.",
    "Objects and lists pass reference pointers to shared heap memory.",
    "Mutating an object inside a function mutates the caller's copy too.",
    "To protect your data, pass a shallow or deep clone (`[...arr]`, structuredClone)."],
 x:{lang:"javascript", code:"function update(num, obj) {\n  num = 99;              // changing local copy (pass by value)\n  obj.name = \"Altered\";  // mutating shared heap object (pass by reference)\n}\n\nlet count = 10;\nlet user = { name: \"Original\" };\nupdate(count, user);\nconsole.log(count);      // 10 (unchanged!)\nconsole.log(user.name);  // \"Altered\" (mutated!)"},
 dg:"pass-by-value",
 r:["Stack and Heap Memory", "Immutability", "Spread Operator", "Pure Function"]},

{t:"Memory Leak", d:"RAM that a program allocated, stopped needing, but forgot to release — causing memory usage to climb until it crashes.", l:"core", g:["basics","bugs","crash-course"],
 b:["Computers have finite physical RAM. In languages like C, you must explicitly free every block of memory you request. In modern garbage-collected languages like JavaScript and Python, memory is freed automatically — but only when there are zero remaining references pointing to it.",
    "A memory leak happens when you accidentally keep a hidden reference to data you are finished with: an uncleared event listener, a global cache array that grows forever, or an active timer loop. Over hours or days, the application consumes more and more RAM until the operating system steps in and kills the process."],
 k:["Unused memory that cannot be reclaimed because a reference still exists.",
    "Common culprits: forgotten event listeners, runaway global caches, lingering timers.",
    "Causes applications to gradually slow down and eventually crash (OOM).",
    "Profile memory using browser DevTools or memory heap profilers."],
 x:{lang:"javascript", code:"const cache = [];\n\n// Memory leak: this array grows on every request and is never cleared\nfunction handleUser(user) {\n  cache.push(user); // holds reference forever in global memory!\n  return user.id;\n}"},
 dg:"memory-leak",
 r:["Garbage Collection", "Stack and Heap Memory", "Runtime Error", "Debugging"]},

]);
